import pandas as pd, numpy as np
for name in ['experiment_9_csv','experiment_10_csv','experiment_11_csv','experiment_4_csv']:
    df = pd.read_csv(eval(name))
    print("===", name, df.columns.tolist())
    # show unique intervention level and mean yield
    for c in df.columns:
        if 'do_' in c or 'Irrig' in c:
            print(c, "unique:", sorted(df[c].dropna().unique())[:10])
    if 'do_IrrigationRate' in df.columns:
        print(df.groupby('do_IrrigationRate')['CropYield'].agg(['mean','count']))
    if 'IrrigationRate' in df.columns and 'do_' not in ''.join(df.columns):
        # bin
        df['bin']=pd.cut(df['IrrigationRate'],5)
        print(df.groupby('bin')['CropYield'].mean())

